//! Walks one crate after type checking and writes what it defines and what
//! each definition refers to.

use std::collections::BTreeSet;
use std::fmt::Write as _;
use std::path::Path;

use rustc_hir as hir;
use rustc_hir::attrs::AttributeKind;
use rustc_hir::def::{DefKind, Res};
use rustc_hir::def_id::{DefId, LocalDefId};
use rustc_hir::intravisit::{self, Visitor};
use rustc_middle::hir::nested_filter;
use rustc_middle::ty::{self, TyCtxt, TypeckResults};
use rustc_span::Span;

/// A definition that owns lines of a source file, or was generated by a macro.
struct Definition {
    id: String,
    /// The last path segment: a function or method name.
    name: String,
    callable: bool,
    /// `module::path::name` when the definition is a test.
    test: Option<String>,
    /// File and one-based first and last line. `None` for generated code,
    /// which owns no line of any file.
    place: Option<(String, usize, usize)>,
}

/// A mention of a definition, with the place it is written.
struct Mention {
    file: String,
    /// One-based.
    line: usize,
    /// Zero-based, in characters.
    column: usize,
    to: String,
    callable: bool,
}

struct Collector<'tcx> {
    tcx: TyCtxt<'tcx>,
    owner: Option<LocalDefId>,
    typeck: Option<&'tcx TypeckResults<'tcx>>,
    definitions: Vec<Definition>,
    mentions: Vec<Mention>,
    /// `(changed, affected)`: a change to the first affects the second.
    affects: BTreeSet<(String, String)>,
}

/// The stable name of a definition: the same string in every crate that
/// refers to it.
fn id_of(tcx: TyCtxt<'_>, def_id: DefId) -> String {
    format!(
        "{}{}",
        tcx.crate_name(def_id.krate),
        tcx.def_path(def_id).to_string_no_crate_verbose()
    )
}

/// The definition a reference to `def_id` counts for. A constructor, variant
/// or field counts for its type; a generic parameter or closure for the item
/// around it. Modules and imports are not nodes: every path goes through one.
fn node_of(tcx: TyCtxt<'_>, mut def_id: DefId) -> Option<DefId> {
    loop {
        match tcx.def_kind(def_id) {
            DefKind::Fn
            | DefKind::AssocFn
            | DefKind::Const { .. }
            | DefKind::AssocConst { .. }
            | DefKind::Static { .. }
            | DefKind::Struct
            | DefKind::Enum
            | DefKind::Union
            | DefKind::Trait
            | DefKind::TraitAlias
            | DefKind::TyAlias
            | DefKind::AssocTy
            | DefKind::Impl { .. }
            | DefKind::Macro(..) => return Some(def_id),
            DefKind::Mod | DefKind::ExternCrate | DefKind::Use | DefKind::ForeignMod => {
                return None;
            }
            _ => def_id = tcx.opt_parent(def_id)?,
        }
    }
}

impl<'tcx> Collector<'tcx> {
    /// Records that the current owner mentions `target` at `span`.
    fn mention(&mut self, target: DefId, span: Span) {
        let Some(owner) = self.owner else { return };
        let Some(target) = node_of(self.tcx, target) else {
            return;
        };
        if target == owner.to_def_id() {
            return;
        }
        // A call to a standard-library trait method that could not be
        // resolved to an impl (`T::default()` for a generic `T`) is kept: it
        // may dispatch to an impl in this workspace. Other mentions of the
        // standard library are dropped.
        let unresolved_dispatch = self.tcx.def_kind(target) == DefKind::AssocFn
            && self.tcx.trait_of_assoc(target).is_some();
        if is_sysroot_crate(self.tcx, target) && !unresolved_dispatch {
            return;
        }
        let to = id_of(self.tcx, target);
        let callable = matches!(self.tcx.def_kind(target), DefKind::Fn | DefKind::AssocFn);
        self.affects
            .insert((to.clone(), id_of(self.tcx, owner.to_def_id())));
        if !span.from_expansion() {
            let source_map = self.tcx.sess.source_map();
            let position = source_map.lookup_char_pos(span.lo());
            if let Some(file) = local_path(&position.file.name) {
                self.mentions.push(Mention {
                    file,
                    line: position.line,
                    column: position.col.0,
                    to,
                    callable,
                });
            }
        }
    }

    /// The function a call to `def_id` runs. For a trait method called on a
    /// type the compiler knows (`Limit::default()`, `token.is_expired()`),
    /// that is the method of the impl; for a call through a generic
    /// parameter or `dyn Trait` it stays the trait method.
    fn callee(&self, def_id: DefId, hir_id: hir::HirId) -> DefId {
        let tcx = self.tcx;
        let (Some(typeck), Some(owner)) = (self.typeck, self.owner) else {
            return def_id;
        };
        if tcx.def_kind(def_id) != DefKind::AssocFn || tcx.trait_of_assoc(def_id).is_none() {
            return def_id;
        }
        let arguments = typeck.node_args(hir_id);
        let environment = ty::TypingEnv::post_analysis(tcx, owner.to_def_id());
        match ty::Instance::try_resolve(tcx, environment, def_id, arguments) {
            Ok(Some(instance)) => instance.def_id(),
            _ => def_id,
        }
    }

    /// Records the item-like `def_id` as a definition and makes it the owner
    /// of what is visited next.
    fn enter(&mut self, def_id: LocalDefId) -> Option<LocalDefId> {
        let tcx = self.tcx;
        let previous = self.owner.replace(def_id);
        let global = def_id.to_def_id();
        let kind = tcx.def_kind(global);
        if node_of(tcx, global) != Some(global) {
            // A module or an import: not a node, and nothing it mentions is
            // attributed to it.
            self.owner = None;
            return previous;
        }
        let id = id_of(tcx, global);

        // A call through `dyn Trait` or a generic parameter names the trait
        // method only, so a change to an impl affects whatever mentions the
        // trait method. The reverse is not recorded: a caller that uses the
        // trait's default body mentions the trait method itself, and tying
        // the trait method to its impls would make every impl of a common
        // trait (`Default`, `From`) affect every other.
        if kind == DefKind::AssocFn {
            if let Some(declaration) = tcx.associated_item(global).trait_item_def_id() {
                if declaration != global {
                    self.affects.insert((id.clone(), id_of(tcx, declaration)));
                }
            }
        }
        // The header of an impl or trait (its generics, bounds, the trait it
        // names) applies to every item inside it.
        if let Some(parent) = tcx.opt_parent(global) {
            if matches!(tcx.def_kind(parent), DefKind::Impl { .. } | DefKind::Trait) {
                self.affects.insert((id_of(tcx, parent), id.clone()));
            }
        }

        let hir_id = tcx.local_def_id_to_hir_id(def_id);
        let span = tcx.hir_span_with_body(hir_id);
        let place = (!span.from_expansion()).then(|| self.lines(hir_id, span)).flatten();
        let path = tcx.def_path(global).to_string_no_crate_verbose();
        let test = is_test_descriptor(tcx, def_id, kind)
            .then(|| path.trim_start_matches("::").to_owned());
        self.definitions.push(Definition {
            name: path.rsplit("::").next().unwrap_or("").to_owned(),
            id,
            callable: matches!(kind, DefKind::Fn | DefKind::AssocFn),
            test,
            place,
        });
        previous
    }

    /// The file and lines of an item, its attributes and doc comments
    /// included.
    fn lines(&self, hir_id: hir::HirId, span: Span) -> Option<(String, usize, usize)> {
        let source_map = self.tcx.sess.source_map();
        let start = source_map.lookup_char_pos(span.lo());
        let end = source_map.lookup_char_pos(span.hi());
        let file = local_path(&start.file.name)?;
        let mut first = start.line;
        for attribute in self.tcx.hir_attrs(hir_id) {
            // Only some attributes keep a span once the compiler has parsed
            // them. A line of one that does not is outside the item's range,
            // and a change there falls back to the whole crate.
            let span = match attribute {
                hir::Attribute::Unparsed(item) => item.span,
                hir::Attribute::Parsed(AttributeKind::DocComment { span, .. }) => *span,
                _ => continue,
            };
            if span.from_expansion() || span.is_dummy() {
                continue;
            }
            let position = source_map.lookup_char_pos(span.lo());
            if position.file.name == start.file.name {
                first = first.min(position.line);
            }
        }
        Some((file, first, end.line))
    }
}

/// The standard library changes with the toolchain, never with a commit, so
/// references into it say nothing about what a change affects.
fn is_sysroot_crate(tcx: TyCtxt<'_>, def_id: DefId) -> bool {
    const SYSROOT: [&str; 5] = ["core", "alloc", "std", "test", "proc_macro"];
    SYSROOT.contains(&tcx.crate_name(def_id.krate).as_str())
}

/// The path of a file as cargo passed it to rustc: relative to the workspace
/// root for workspace crates.
fn local_path(name: &rustc_span::FileName) -> Option<String> {
    match name {
        rustc_span::FileName::Real(real) => {
            Some(real.local_path()?.to_string_lossy().into_owned())
        }
        _ => None,
    }
}

/// The test harness turns each `#[test]` function into a constant of type
/// `test::TestDescAndFn` with the function's own path. That constant marks
/// the test, whichever attribute macro (`test`, `tokio::test`) wrote it.
fn is_test_descriptor(tcx: TyCtxt<'_>, def_id: LocalDefId, kind: DefKind) -> bool {
    if !matches!(kind, DefKind::Const { .. }) {
        return false;
    }
    match tcx.type_of(def_id).skip_binder().kind() {
        ty::Adt(adt, _) => tcx.def_path_str(adt.did()).ends_with("TestDescAndFn"),
        _ => false,
    }
}

impl<'tcx> Visitor<'tcx> for Collector<'tcx> {
    type NestedFilter = nested_filter::OnlyBodies;

    fn maybe_tcx(&mut self) -> Self::MaybeTyCtxt {
        self.tcx
    }

    fn visit_item(&mut self, item: &'tcx hir::Item<'tcx>) {
        let previous = self.enter(item.owner_id.def_id);
        intravisit::walk_item(self, item);
        self.owner = previous;
    }

    fn visit_trait_item(&mut self, item: &'tcx hir::TraitItem<'tcx>) {
        let previous = self.enter(item.owner_id.def_id);
        intravisit::walk_trait_item(self, item);
        self.owner = previous;
    }

    fn visit_impl_item(&mut self, item: &'tcx hir::ImplItem<'tcx>) {
        let previous = self.enter(item.owner_id.def_id);
        intravisit::walk_impl_item(self, item);
        self.owner = previous;
    }

    fn visit_foreign_item(&mut self, item: &'tcx hir::ForeignItem<'tcx>) {
        let previous = self.enter(item.owner_id.def_id);
        intravisit::walk_foreign_item(self, item);
        self.owner = previous;
    }

    fn visit_nested_body(&mut self, id: hir::BodyId) {
        let previous = self.typeck.replace(self.tcx.typeck_body(id));
        let body = self.tcx.hir_body(id);
        self.visit_body(body);
        self.typeck = previous;
    }

    fn visit_path(&mut self, path: &hir::Path<'tcx>, id: hir::HirId) {
        if let Res::Def(_, def_id) = path.res {
            let span = path.segments.last().map_or(path.span, |segment| segment.ident.span);
            self.mention(self.callee(def_id, id), span);
        }
        intravisit::walk_path(self, path);
    }

    fn visit_qpath(&mut self, qpath: &'tcx hir::QPath<'tcx>, id: hir::HirId, _span: Span) {
        // `Type::function` and `<T as Trait>::function` are resolved by type
        // checking, not by name resolution.
        if let (hir::QPath::TypeRelative(_, segment), Some(typeck)) = (qpath, self.typeck) {
            if let Some(def_id) = typeck.qpath_res(qpath, id).opt_def_id() {
                self.mention(self.callee(def_id, id), segment.ident.span);
            }
        }
        intravisit::walk_qpath(self, qpath, id);
    }

    fn visit_expr(&mut self, expression: &'tcx hir::Expr<'tcx>) {
        if let (hir::ExprKind::MethodCall(segment, ..), Some(typeck)) =
            (&expression.kind, self.typeck)
        {
            if let Some(def_id) = typeck.type_dependent_def_id(expression.hir_id) {
                self.mention(self.callee(def_id, expression.hir_id), segment.ident.span);
            }
        }
        intravisit::walk_expr(self, expression);
    }
}

/// Writes the records of the crate being compiled into `directory`.
pub fn write(tcx: TyCtxt<'_>, directory: &Path) -> std::io::Result<()> {
    let started = std::time::Instant::now();
    let mut collector = Collector {
        tcx,
        owner: None,
        typeck: None,
        definitions: Vec::new(),
        mentions: Vec::new(),
        affects: BTreeSet::new(),
    };
    tcx.hir_visit_all_item_likes_in_crate(&mut collector);

    // One file per crate and kind of build, overwritten by each compile, so
    // the directory always describes the latest build.
    let kind = if tcx.sess.opts.test {
        "test".to_owned()
    } else {
        let types: Vec<String> = tcx
            .crate_types()
            .iter()
            .map(|crate_type| format!("{crate_type:?}").to_lowercase())
            .collect();
        types.join("-")
    };
    // cargo tells rustc which package it is building.
    let package = std::env::var("CARGO_PKG_NAME").unwrap_or_default();
    let crate_name = tcx.crate_name(rustc_hir::def_id::LOCAL_CRATE);

    let mut json = String::new();
    // How long the walk took, to keep an eye on what recording costs.
    let _ = write!(
        json,
        "{{\n\"package\":{},\n\"record_ms\":{},\n\"definitions\":[",
        quote(&package),
        started.elapsed().as_millis()
    );
    for (index, definition) in collector.definitions.iter().enumerate() {
        let separator = if index == 0 { "\n" } else { ",\n" };
        let _ = write!(
            json,
            "{separator}{{\"id\":{},\"name\":{},\"callable\":{}",
            quote(&definition.id),
            quote(&definition.name),
            definition.callable
        );
        if let Some(test) = &definition.test {
            let _ = write!(json, ",\"test\":{}", quote(test));
        }
        if let Some((file, first, last)) = &definition.place {
            let _ = write!(json, ",\"file\":{},\"first_line\":{first},\"last_line\":{last}", quote(file));
        }
        json.push('}');
    }
    json.push_str("\n],\n\"mentions\":[");
    for (index, mention) in collector.mentions.iter().enumerate() {
        let separator = if index == 0 { "\n" } else { ",\n" };
        let _ = write!(
            json,
            "{separator}{{\"file\":{},\"line\":{},\"column\":{},\"to\":{},\"callable\":{}}}",
            quote(&mention.file),
            mention.line,
            mention.column,
            quote(&mention.to),
            mention.callable
        );
    }
    json.push_str("\n],\n\"affects\":[");
    for (index, (changed, affected)) in collector.affects.iter().enumerate() {
        let separator = if index == 0 { "\n" } else { ",\n" };
        let _ = write!(json, "{separator}[{},{}]", quote(changed), quote(affected));
    }
    json.push_str("\n]\n}\n");

    std::fs::create_dir_all(directory)?;
    std::fs::write(directory.join(format!("{crate_name}.{kind}.json")), json)
}

/// A JSON string literal.
fn quote(text: &str) -> String {
    let mut quoted = String::with_capacity(text.len() + 2);
    quoted.push('"');
    for c in text.chars() {
        match c {
            '"' => quoted.push_str("\\\""),
            '\\' => quoted.push_str("\\\\"),
            '\n' => quoted.push_str("\\n"),
            c if c.is_control() => {
                let _ = write!(quoted, "\\u{:04x}", c as u32);
            }
            c => quoted.push(c),
        }
    }
    quoted.push('"');
    quoted
}
